//! 🪞️ Public original projections retain their real parent and every cancelled receiving prefix.
use semio_framework_test_fixtures::fixture_text;
pub use semio_framework_value_native_owned::*;
pub use semio_framework_value_native_owned::owned::*;
pub use semio_framework_value_native_owned::retained_clone::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneRef,RetainedCloneStep,RetainedCloneSource,retained_clone_grant_admits};
pub use semio_framework_value_retirement::retirement::RetireOwned;
pub use semio_framework_value_derive::{RetireOwned,NativeReceive};
pub use semio_framework_value_testing_admission as source_fixture;
pub fn observe_retirement_allocations<T>(f:impl FnOnce()->T)->(T,(usize,usize)){semio_framework_value_testing_allocator::observe_retirement_allocations(f)}
use crate::{DslValue,RetainedWorkOutcome,OriginalReceivingPrimary,retirement::controlled::ControlledRetirement,shared_issuance::SealedShared};
#[derive(crate::RetireOwned,crate::NativeReceive)]#[value(crate="crate",native_owned="crate")]struct Row{value:SealedShared<String>}
struct Bank{left:RetainedCloneGrant,fuel:u64}
impl Bank{fn new()->Self{let f:serde_json::Value=serde_json::from_str(include_str!("../../../🧳️original/🧪️tests/🎟️work/📐️.json")).unwrap();Self{left:RetainedCloneGrant{maximum_items:f["items"].as_u64().unwrap()as usize,maximum_copy_bytes:f["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:f["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:f["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:f["depth"].as_u64().unwrap()as usize},fuel:f["fuel"].as_u64().unwrap()}}fn offer(&self)->RetainedCloneGrant{assert!(self.fuel>0);RetainedCloneGrant{maximum_items:self.left.maximum_items.min(1),maximum_copy_bytes:self.left.maximum_copy_bytes.min(4096),..self.left}}fn quoted(&self,d:RetirementDemand)->RetainedCloneGrant{let loan=self.offer();assert!(retained_clone_grant_admits(loan,d));RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth,..loan}}fn post(&mut self,p:RetainedCloneProgress,work:u64){assert!(p.fits(self.left));self.left.maximum_items-=p.copied_items;self.left.maximum_copy_bytes-=p.copied_bytes;self.left.maximum_capacity_bytes-=p.retained_capacity_bytes;self.left.maximum_release_bytes-=p.released_bytes;self.fuel=self.fuel.checked_sub(work).unwrap();}}
fn observe<R>(run:impl FnOnce()->R)->(R,(usize,usize)){semio_framework_value_testing_allocator::observe_retirement_allocations(run)}
fn account(bank:&mut Bank,p:RetainedCloneProgress,work:u64,g:RetainedCloneGrant,heap:(usize,usize)){assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.post(p,work);}
fn denied(d:RetirementDemand,g:RetainedCloneGrant)->impl Iterator<Item=RetainedCloneGrant>{[(true,RetainedCloneGrant{maximum_items:0,..g}),(d.copy_bytes>0,RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g}),(d.capacity_bytes>0,RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g}),(d.release_bytes>0,RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g}),(d.depth>0,RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g})].into_iter().filter_map(|(active,g)|active.then_some(g))}
struct ConstructionLoan{loan:RetainedCloneGrant,granted:bool,accepted:bool,submitted:RetainedCloneProgress}
impl crate::NativeDecodeConstructionRecipient for ConstructionLoan{fn submitted(&self)->RetainedCloneProgress{self.submitted}fn grant(&mut self,d:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{assert!(!self.granted);assert!(crate::retained_clone::retained_clone_grant_admits(self.loan,d));self.granted=true;Ok(self.loan)}fn accept(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),ValueError>{self.submitted=self.submitted.checked_add(p)?;assert!(!self.accepted);assert!(p.fits(g)&&p.fits(self.loan));assert!(g.maximum_items<=self.loan.maximum_items&&g.maximum_copy_bytes<=self.loan.maximum_copy_bytes&&g.maximum_capacity_bytes<=self.loan.maximum_capacity_bytes&&g.maximum_release_bytes<=self.loan.maximum_release_bytes&&g.maximum_depth<=self.loan.maximum_depth);self.accepted=true;Ok(())}}
fn receive(control:&mut NativeDecodeControl<'_>,loan:RetainedCloneGrant,mut work_loan:crate::source_fixture::WorkLoan<'_>,operation:impl FnOnce(&mut NativeDecodeControl<'_>)->RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>)->RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>{let mut recipient=ConstructionLoan{loan,granted:false,accepted:false,submitted:Default::default()};let mut construction_issuer=crate::native_decoding::NativeConstructionRecipientIssuer::new();let mut construction_loan=construction_issuer.loan(&mut recipient);let mut work_issuer=crate::native_decoding::NativeDecodeWorkIssuer::new();let mut native_work_loan=work_issuer.loan(&mut work_loan);let mut work=0;let result=control.with_work_recipient(&mut native_work_loan,|control|control.with_construction_recipient(&mut construction_loan,|control|{let turn=operation(control);work=turn.work;turn.result}));RetainedWorkOutcome{result,work}}
fn input(bank:&mut Bank)->RetainedCloneSource<DslValue>{let original=DslValue::Object(vec![("value".into(),DslValue::String("Original receiving owner🧱".into()))]);crate::source_fixture::capture(original,bank,Bank::offer,|bank|bank.fuel,|bank,p,work,heap,g|account(bank,p,work,g,heap))}
fn drain<T:RetireOwned>(value:T,bank:&mut Bank){let mut close=ControlledRetirement::new(value).unwrap_or_else(|_|panic!("original receiving typed close unsupported"));for _ in 0..10000{if close.terminal_is_empty(){return}let g=bank.quoted(close.next_demand(4096).unwrap());let(result,heap)=observe(||close.step(g));let work=close.last_turn_work();let p=match &result{Ok(s)=>s.progress(),Err(e)=>e.retained_progress()};account(bank,p,work,g,heap);result.unwrap();}panic!("original receiving typed close stalled")}

